"use client"

import * as React from "react"
import { accentChain } from "glimm"
import { GlimmScope, type GlimmScopeHandle } from "glimm/react"

const palette = accentChain(["#CB30E0", "#FF2D55", "#FF8D28", "#FFCC00"])
const skeleton = "#ededee"
function Bar({ width, height = 8, tone = skeleton }: { width: number | string; height?: number; tone?: string }) { return <span aria-hidden="true" style={{ background: tone, borderRadius: 5, display: "block", height, width }} /> }

function Editor() {
  return <div style={{ display: "flex", flex: 1, minHeight: 0 }}>
    <aside style={{ borderRight: "1px solid #e7e7e8", padding: "16px 12px", width: 208 }}><Bar width={62} /><div style={{ height: 14 }} />{[148, 120, 104, 132, 88, 110, 140].map((w, i) => <div key={i} style={{ alignItems: "center", display: "flex", gap: 8, padding: "5px 0", paddingLeft: i === 1 || i === 2 || i === 4 || i === 5 ? 16 : 0 }}><Bar height={13} width={13} /><Bar width={w} /></div>)}</aside>
    <div style={{ alignItems: "flex-start", background: "#f1f1f1", display: "flex", flex: 1, justifyContent: "center", overflow: "auto", padding: "44px 24px" }}><div style={{ background: "#fff", outline: "1px solid #0d99ff", padding: "26px 28px 34px", position: "relative", width: "min(468px,100%)" }}>
      {[[-3,-3],[-3,null],[null,-3],[null,null]].map((_, i) => <span key={i} style={{ background: "#fff", border: "1px solid #0d99ff", height: 7, left: i % 2 ? undefined : -4, position: "absolute", right: i % 2 ? -4 : undefined, top: i < 2 ? -4 : undefined, bottom: i >= 2 ? -4 : undefined, width: 7 }} />)}
      <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 44 }}><Bar height={10} tone="#dededf" width={54} /><div style={{ display: "flex", gap: 13 }}><Bar width={32} /><Bar width={32} /><Bar width={32} /></div><Bar height={22} width={50} /></div>
      <Bar height={21} tone="#dededf" width="64%" /><div style={{ height: 9 }} /><Bar height={21} tone="#dededf" width="46%" />
      <div style={{ display: "grid", gap: 8, marginTop: 36 }}><Bar height={9} width="100%" /><Bar height={9} width="97%" /><Bar height={9} width="74%" /></div><div style={{ display: "grid", gap: 8, marginTop: 18 }}><Bar height={9} width="92%" /><Bar height={9} width="60%" /></div>
      <div style={{ background: skeleton, borderRadius: 6, height: 176, marginTop: 32 }} /><div style={{ display: "flex", gap: 10, marginTop: 28 }}><Bar height={32} tone="#dededf" width={104} /><Bar height={32} width={78} /></div>
    </div></div>
    <aside style={{ borderLeft: "1px solid #e7e7e8", padding: "16px 14px", width: 220 }}><Bar width={38} /><div style={{ display: "grid", gap: 8, marginTop: 14 }}>{Array.from({ length: 6 }, (_, i) => <Bar height={26} key={i} width="100%" />)}</div><div style={{ height: 24 }} /><Bar width={62} /><div style={{ display: "grid", gap: 8, marginTop: 14 }}><Bar height={28} width="100%" /><Bar height={28} width="100%" /><Bar height={28} width="100%" /></div></aside>
  </div>
}

function Success({ onBack }: { onBack: () => void }) {
  return <main style={{ background: "#fff", height: "100%", position: "relative" }}><button onClick={onBack} style={{ background: "#fff", border: "1px solid #e6e6e7", borderRadius: 999, left: 32, padding: "7px 14px", position: "absolute", top: 20 }}>Back</button><div style={{ alignItems: "center", display: "flex", flexDirection: "column", left: "50%", position: "absolute", top: "23%", transform: "translateX(-50%)", width: 380 }}><div style={{ alignItems: "center", background: "#4ea36b", borderRadius: 999, color: "#fff", display: "flex", fontSize: 20, height: 34, justifyContent: "center", width: 34 }}>✓</div><div style={{ height: 26 }} /><Bar height={14} tone="#dededf" width={96} /><div style={{ height: 14 }} /><Bar height={9} width={172} /><div style={{ border: "1px solid #e1e1e2", borderRadius: 10, marginTop: 26, padding: 16, width: "100%" }}><Bar height={14} width="88%" /><div style={{ height: 18 }} /><Bar height={10} tone="#dededf" width="76%" /><div style={{ display: "grid", gap: 8, marginTop: 28 }}><Bar width="100%" /><Bar width="92%" /><Bar width="56%" /></div><div style={{ background: skeleton, borderRadius: 5, height: 72, marginTop: 16 }} /></div></div></main>
}

function PublishScene() {
  const scope = React.useRef<GlimmScopeHandle>(null)
  const button = React.useRef<HTMLButtonElement>(null)
  const [busy, setBusy] = React.useState(false)
  const [published, setPublished] = React.useState(false)
  const publish = () => { if (busy) return; setBusy(true); const r = button.current?.getBoundingClientRect(); scope.current?.play({ at: r ? [r.left + r.width / 2, r.top + r.height / 2] : undefined, work: () => new Promise((resolve) => window.setTimeout(resolve, 1400)), change: () => setPublished(true), onLeave: () => setBusy(false) }) }
  return <GlimmScope ref={scope} palette={palette} sweepMs={2700} style={{ inset: 0, position: "absolute" }}><div style={{ background: "#fff", color: "#242529", fontFamily: "Inter, ui-sans-serif, system-ui, sans-serif", height: "100%", minHeight: 560, overflow: "hidden" }}>{published ? <Success onBack={() => setPublished(false)} /> : <main style={{ display: "flex", flexDirection: "column", height: "100%" }}><header style={{ alignItems: "center", borderBottom: "1px solid #e7e7e8", display: "flex", height: 52, justifyContent: "space-between", padding: "0 14px" }}><Bar height={14} tone="#dededf" width={52} /><Bar height={25} width={104} /><div style={{ alignItems: "center", display: "flex", gap: 10 }}><span style={{ fontFamily: "cursive", fontSize: 16, transform: "rotate(-2deg)" }}>{!busy && "Click Publish →"}</span><button ref={button} disabled={busy} onClick={publish} style={{ background: "#242529", border: 0, borderRadius: 999, color: "#fff", height: 38, minWidth: 80, padding: "0 16px" }}>{busy ? "◌  Publishing" : "Publish"}</button></div></header><Editor /></main>}</div></GlimmScope>
}

export default function GlimmPublish() { return <PublishScene /> }
export { GlimmPublish }
